=<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>SharePoint Page Preview</title>
  <style>
    * { box-sizing: border-box; margin: 0; padding: 0; }
    body {
      font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
      background-color: #f3f2f1;
      padding: 32px 16px;
      color: #323130;
    }
    .wrapper {
      max-width: 860px;
      margin: 0 auto;
    }
    .header-banner {
      background-color: #0078d4;
      color: #ffffff;
      padding: 20px 32px;
      border-radius: 8px 8px 0 0;
      display: flex;
      align-items: center;
      gap: 12px;
    }
    .header-banner h1 {
      font-size: 22px;
      font-weight: 600;
    }
    .header-banner .badge {
      background: rgba(255,255,255,0.2);
      border-radius: 4px;
      padding: 2px 10px;
      font-size: 12px;
      letter-spacing: 0.5px;
      text-transform: uppercase;
    }
    .card {
      background: #ffffff;
      border-radius: 0 0 8px 8px;
      box-shadow: 0 2px 8px rgba(0,0,0,0.12);
      overflow: hidden;
    }
    .meta-bar {
      background: #f8f8f8;
      border-bottom: 1px solid #edebe9;
      padding: 12px 32px;
      display: flex;
      gap: 32px;
      font-size: 13px;
      color: #605e5c;
    }
    .meta-bar span strong {
      color: #323130;
    }
    .page-preview {
      padding: 32px;
    }
    .page-preview h2 {
      font-size: 28px;
      font-weight: 700;
      color: #0078d4;
      margin-bottom: 24px;
      padding-bottom: 12px;
      border-bottom: 2px solid #edebe9;
    }
    .content-body {
      font-size: 15px;
      line-height: 1.7;
      color: #323130;
    }
    .content-body h1, .content-body h2, .content-body h3 {
      margin-top: 20px;
      margin-bottom: 8px;
      color: #201f1e;
    }
    .content-body p { margin-bottom: 12px; }
    .content-body ul, .content-body ol {
      margin: 8px 0 12px 24px;
    }
    .content-body a { color: #0078d4; }
    .content-body table {
      width: 100%;
      border-collapse: collapse;
      margin-bottom: 16px;
    }
    .content-body th, .content-body td {
      border: 1px solid #edebe9;
      padding: 8px 12px;
      text-align: left;
    }
    .content-body th { background: #f3f2f1; font-weight: 600; }
    .action-section {
      padding: 24px 32px;
      background: #f3f2f1;
      border-top: 1px solid #edebe9;
      text-align: center;
    }
    .action-section p {
      margin-bottom: 18px;
      font-size: 14px;
      color: #605e5c;
    }
    .btn {
      display: inline-block;
      padding: 12px 32px;
      border-radius: 4px;
      font-size: 15px;
      font-weight: 600;
      text-decoration: none;
      margin: 0 8px;
      letter-spacing: 0.2px;
    }
    .btn-approve {
      background-color: #107c10;
      color: #ffffff;
    }
    .btn-reject {
      background-color: #d13438;
      color: #ffffff;
    }
    .footer {
      margin-top: 16px;
      font-size: 12px;
      color: #a19f9d;
    }
  </style>
</head>
<body>
  <div class="wrapper">
    <div class="header-banner">
      <h1>SharePoint Page Update Preview</h1>
      <span class="badge">Pending Approval</span>
    </div>
    <div class="card">
      <div class="meta-bar">
        <span><strong>Site ID:</strong> {{ $json.siteId }}</span>
        <span><strong>Author:</strong> {{ $json.authorName }}</span>
        <span><strong>Submitted:</strong> {{ $json.submittedAt }}</span>
      </div>
      <div class="page-preview">
        <h2>{{ $json.pageTitle }}</h2>
        <div class="content-body">{{ $json.pageContent }}</div>
      </div>
      <div class="action-section">
        <p>Please review the page content above and click <strong>Approve</strong> to publish or <strong>Reject</strong> to discard the update.</p>
        <a class="btn btn-approve" href="{{ $execution.resumeUrl }}?action=approve">Approve</a>
        <a class="btn btn-reject" href="{{ $execution.resumeUrl }}?action=reject">Reject</a>
        <div class="footer">This preview was generated automatically by n8n. Do not reply to this email.</div>
      </div>
    </div>
  </div>
</body>
</html>
